style.css:
@-moz-document domain("roblox.com") {
body, .content, .container, #app-container {
        background-image: url("https://i.imgur.com/YOURIMAGEURL.jpg"); /* Cambia esta URL */
        background-size: cover;
        background-attachment: fixed;
        background-position: center;
        background-repeat: no-repeat;
    }

    /* Hacer transparente el contenido */
    .container, .content, #app-container {
        background-color: rgba(0,0,0,0.4) !important; /* Ajusta la opacidad */
    }

    /* Opcional: cambiar color de texto para que se lea mejor */
    * {
        color: white !important;
    }
}
